import pandas as pd
import os

# Check the input data directory
input_dir = r"C:\Users\sandeeppawar\Downloads\aida-eval\data\file_generation_en"

# Search for price_fill.xlsx in subdirectories
for root, dirs, files in os.walk(input_dir):
    for file in files:
        if 'price_fill' in file.lower() and file != 'price_fill_res.xlsx':
            full_path = os.path.join(root, file)
            print(f"Found: {full_path}")

            try:
                df = pd.read_excel(full_path, sheet_name='Sheet1')
                print(f"  Shape: {df.shape}")
                print(f"  Columns: {list(df.columns)}")

                # Check row 51
                if 51 < len(df):
                    print(f"  Row 51 - Spec: {df.loc[51, 'Specification/model']}, Price: {df.loc[51, 'Price']}")

                # Check rows 281-285 (the ones with NaN in ref but values in pred)
                for idx in [281, 282, 284, 285]:
                    if idx < len(df):
                        print(f"  Row {idx} - Spec: {df.loc[idx, 'Specification/model']}, Price: {df.loc[idx, 'Price']}")
            except Exception as e:
                print(f"  Error reading: {e}")
            print()
